// Üretilen dosya: tool/ozgun/uret.py. Matematik ve Geometri · Katı cisimler ve uzay geometrisi: prizma, piramit, silindir, koni, küre, kesit ve açınım problemleri (kolay).
const ozMathematics17Kolay = <(String, String, List<String>, String)>[
  ('Bir dikdörtgenler prizmasının ayrıt uzunlukları a, b ve c birim olduğunda cisim köşegeninin uzunluğunu veren genel bağıntı aşağıdakilerden hangisidir?', '√(a² + b² + c²)', ['√(a² + b² - c²)', '√(ab + bc + ac)', 'a + b + c'], 'Dikdörtgenler prizmasında cisim köşegeni, taban köşegeni √(a² + b²) ile yükseklik c\'nin oluşturduğu dik üçgenin hipotenüsü olduğundan √(a² + b² + c²) formülüyle bulunur.'),
  ('Tabanı sekizgen olan bir dik prizmanın toplam kaç tane yüzü vardır?', '10 yüzü', ['12 yüzü', '16 yüzü', '24 yüzü'], 'n kenarlı bir dik prizmanın n tane yanal yüzü ve 2 tane tabanı olmak üzere toplam n + 2 yüzü vardır; sekizgen prizmada 8 + 2 = 10 yüz bulunur.'),
  ('Bir küpün cisim köşegeninin uzunluğu, bir ayrıtının uzunluğunun kaç katına eşittir?', '√3 katına', ['√2 katına', '2√2 katına', '3 katına'], 'Ayrıtı a olan küpün taban köşegeni a√2, cisim köşegeni ise √(a² + a² + a²) = a√3 olduğundan ayrıtın √3 katıdır.'),
  ('Farklı üç ayrıtının uzunlukları 2 cm, 3 cm ve 6 cm olan bir dikdörtgenler prizmasının cisim köşegeni kaç santimetredir?', '7 santimetre', ['8 santimetre', '√45 santimetre', '11 santimetre'], 'Cisim köşegeni e = √(2² + 3² + 6²) = √(4 + 9 + 36) = √49 = 7 cm olarak hesaplanır.'),
  ('Tabanı beşgen olan bir dik prizmanın köşe sayısı ile ayrıt sayısının toplamı kaçtır?', '25', ['20', '22', '30'], 'Beşgen prizmanın 2×5 = 10 köşesi ve 3×5 = 15 ayrıtı vardır; toplamları 10 + 15 = 25 eder.'),
  ('Bir küpün düzlemsel açınımı yapıldığında birbirine eş kaç adet karesel bölge elde edilir?', '6 adet karesel bölge', ['4 adet karesel bölge', '8 adet karesel bölge', '12 adet karesel bölge'], 'Küpün 6 eş kare yüzü bulunduğundan düzlemsel açınımı daima 6 adet eş karesel bölgeden oluşur.'),
  ('Yüzey alanı 96 birimkare olan bir küpün hacmi kaç birimküptür?', '64 birimküp', ['48 birimküp', '128 birimküp', '32 birimküp'], 'Küpün yüzey alanı 6a² = 96 ise a² = 16 ve bir ayrıtı a = 4 birimdir; hacmi a³ = 4³ = 64 birimküptür.'),
  ('Düzgün dörtyüzlü olarak adlandırılan özel piramidin tüm yüzleri hangi geometrik şekilden oluşur?', 'Eşkenar üçgen', ['İkizkenar dik üçgen', 'Düzgün beşgen', 'Eşkenar dörtgen'], 'Düzgün dörtyüzlü, 4 yüzü de birbirine eş eşkenar üçgenlerden oluşan özel bir üçgen piramittir.'),
  ('Taban ayrıtı 6 cm ve yüksekliği 4 cm olan kare dik piramidin hacmi kaç santimetreküptür?', '48 santimetreküp', ['72 santimetreküp', '144 santimetreküp', '36 santimetreküp'], 'Piramidin hacmi (Taban Alanı × Yükseklik) / 3 formülüyle (6² × 4) / 3 = 144 / 3 = 48 cm³ bulunur.'),
  ('Bir dik prizmanın yanal alanı hesaplanırken taban çevresi ile hangi uzunluk çarpılır?', 'Prizmanın yüksekliği', ['Prizmanın taban köşegeni', 'Prizmanın cisim köşegeni', 'Tabanın iç teğet yarıçapı'], 'Dik prizmalarda yanal yüzlerin açınımı bir dikdörtgen oluşturur; bu dikdörtgenin bir kenarı taban çevresi, diğer kenarı ise prizmanın yüksekliğidir.'),
  ('Bir kare dik piramidin toplam kaç tane ayrıtı ve kaç tane köşesi vardır?', '8 ayrıtı ve 5 köşesi', ['12 ayrıtı ve 8 köşesi', '6 ayrıtı ve 4 köşesi', '8 ayrıtı ve 4 köşesi'], 'Kare piramidin tabanında 4, yanlarda 4 olmak üzere 8 ayrıtı; tabanda 4 ve tepede 1 olmak üzere 5 köşesi vardır.'),
  ('Cisim köşegeninin uzunluğu 5√3 cm olan bir küpün tüm ayrıtlarının uzunlukları toplamı kaç santimetredir?', '60 santimetre', ['30 santimetre', '45 santimetre', '60√3 santimetre'], 'Küpün cisim köşegeni a√3 = 5√3 olduğundan bir ayrıtı a = 5 cm\'dir; küpün 12 ayrıtı olduğundan toplam uzunluk 12 × 5 = 60 cm olur.'),
  ('Tabana paralel bir düzlemle kesilen düzgün kare piramidin taban ile kesit düzlemi arasında kalan alt kısmına verilen ad nedir?', 'Kesik kare piramit', ['Kare dik prizma', 'Eğik kare prizma', 'Düzgün sekizyüzlü'], 'Bir piramidin tabana paralel bir düzlemle kesilmesi sonucu tepe kısmındaki küçük piramit ayrıldığında kalan alt cisme kesik piramit denir.'),
  ('Taban dik kenarları 3 cm ve 4 cm olan dik üçgen dik prizmanın yüksekliği 10 cm ise yanal alanı kaç santimetrekaredir?', '120 santimetrekare', ['60 santimetrekare', '132 santimetrekare', '140 santimetrekare'], 'Taban hipotenüsü 5 cm olduğundan taban çevresi 3 + 4 + 5 = 12 cm\'dir; yanal alan 12 × 10 = 120 cm² olur.'),
  ('Bir düzgün kesik kare piramidin yan yüzleri hangi geometrik şekillerden meydana gelir?', 'İkizkenar yamuk', ['Eşkenar dörtgen', 'Dikdörtgen', 'İkizkenar üçgen'], 'Düzgün kare piramit tabana paralel kesildiğinde eş ikizkenar üçgen olan yan yüzlerin alt kısımları birer eş ikizkenar yamuk oluşturur.'),
  ('Standart bir küp açınımında, doğrusal dizilmiş 4 eş kareden 1. ve 3. sıradaki kareler küp kapatıldığında birbirine göre hangi konumda bulunur?', 'Karşılıklı paralel yüzler', ['Ortak ayrıtlı komşu yüzler', 'Yalnızca tek köşesi ortak yüzler', 'Üst üste çakışan yüzler'], 'Küp açınımlarında aynı doğrultuda aralarında bir kare boşluk bulunan yüzler küp kapatıldığında birbirine paralel karşılıklı yüzler olur.'),
  ('Ayrıtları 4 cm, 5 cm ve 8 cm olan dikdörtgenler prizmasının tüm yüzey alanı kaç santimetrekaredir?', '184 santimetrekare', ['160 santimetrekare', '92 santimetrekare', '200 santimetrekare'], 'Yüzey alanı 2(ab + bc + ac) = 2(4×5 + 5×8 + 4×8) = 2(20 + 40 + 32) = 2 × 92 = 184 cm² olarak bulunur.'),
  ('Euler çokyüzlüler teoremine göre dışbükey bir prizma veya piramitte Yüz (Y), Köşe (K) ve Ayrıt (A) sayıları arasındaki değişmez eşitlik hangisidir?', 'Y + K - A = 2', ['Y + A - K = 2', 'K + A - Y = 2', 'Y + K + A = 12'], 'Tüm dışbükey çokyüzlülerde yüz sayısı ile köşe sayısının toplamından ayrıt sayısı çıkarıldığında sonuç daima 2\'dir.'),
  ('Taban ayrıtı 4 birim ve yüksekliği 5√3 birim olan düzgün altıgen dik prizmanın hacmi kaç birimküptür?', '360 birimküp', ['120√3 birimküp', '240 birimküp', '180 birimküp'], 'Düzgün altıgenin alanı 6 × (4²√3 / 4) = 24√3 birimkaredir; hacim 24√3 × 5√3 = 24 × 5 × 3 = 360 birimküptür.'),
  ('İçinde bir miktar su bulunan dikdörtgenler prizması biçimindeki kapalı bir kap, farklı bir yüzeyi üzerine yatırıldığında içindeki suyun hangi özelliği kesinlikle değişmez?', 'Suyun kapladığı hacim', ['Suyun kap tabanındaki yüksekliği', 'Suyun temas ettiği ıslak yüzey alanı', 'Suyun üst yüzeyinin alanı'], 'Kap kapalı olduğundan su miktarı sabittir; kabın duruşu değişse bile içindeki suyun hacmi sabit kalır.'),
  ('Bir ayrıtı 6 cm olan küpün bir yüzünün köşegeni ile cisim köşegeninin uzunlukları çarpımı kaç santimetrekaredir?', '36√6 santimetrekare', ['36√3 santimetrekare', '18√6 santimetrekare', '72 santimetrekare'], 'Yüzey köşegeni 6√2 cm ve cisim köşegeni 6√3 cm olduğundan çarpımları 6√2 × 6√3 = 36√6 cm² olur.'),
  ('Düzgün kare piramidin tepe noktasından taban düzlemine indirilen dikmenin ayağı tabanda hangi noktaya karşılık gelir?', 'Karenin köşegenlerinin kesim noktasına', ['Karenin herhangi bir köşesine', 'Karenin bir kenarının orta noktasına', 'Karenin dış bölgesindeki bir noktaya'], 'Düzgün piramitlerde tepe noktasının tabandaki dik izdüşümü, taban düzgün çokgeninin ağırlık merkezi yani karede köşegenlerin kesim noktasıdır.'),
  ('Taban ayrıtları 6 m ve 8 m olan dikdörtgenler prizması şeklindeki bir odanın yüksekliği 5 m ise odanın taban köşegeni kaç metredir?', '10 metre', ['5√5 metre', '14 metre', '12 metre'], 'Taban dik kenarları 6 m ve 8 m olan bir dikdörtgen olduğundan taban köşegeni √(6² + 8²) = 10 metredir.'),
  ('Tabanı ongen olan bir düzgün piramidin toplam kaç tane ayrıtı vardır?', '20 tane ayrıtı', ['10 tane ayrıtı', '30 tane ayrıtı', '11 tane ayrıtı'], 'n kenarlı bir piramidin n tane taban ayrıtı ve n tane yan ayrıtı olmak üzere toplam 2n ayrıtı vardır; ongen piramitte 2 × 10 = 20 ayrıt bulunur.'),
  ('Bir dikdörtgenler prizmasında birbirine paralel ve eş olmayan en fazla kaç farklı dikdörtgensel yüz çeşidi bulunabilir?', '3 farklı yüz çeşidi', ['2 farklı yüz çeşidi', '4 farklı yüz çeşidi', '6 farklı yüz çeşidi'], 'Ayrıtları a, b ve c birbirinden farklı olduğunda ab, bc ve ac alanlı olmak üzere en fazla 3 farklı dikdörtgen yüz çeşidi bulunur.'),
  ('Bir kare dik prizmayı bir küpten ayıran temel geometrik özellik aşağıdakilerden hangisidir?', 'Yan yüz yüksekliğinin taban ayrıtından farklı olabilmesi', ['Taban açılarının 90 dereceden farklı olması', 'Karşılıklı yan yüzlerinin paralel olmaması', 'Toplam köşe sayısının küpten fazla olması'], 'Kare dik prizmada alt ve üst taban karedir ancak yan ayrıt (yükseklik) taban ayrıtına eşit olmak zorunda değildir; eşit olduğunda cisim küp adını alır.'),
  ('Bir küpün bir köşesinden geçen kaç tane yüzey köşegeni ve kaç tane cisim köşegeni vardır?', '3 yüzey köşegeni ve 1 cisim köşegeni', ['2 yüzey köşegeni ve 2 cisim köşegeni', '6 yüzey köşegeni ve 4 cisim köşegeni', '3 yüzey köşegeni ve 3 cisim köşegeni'], 'Küpün bir köşesinde birleşen 3 yüzün her birinde o köşeden çıkan 1\'er yüzey köşegeni (toplam 3) ve en uzak karşı köşeye giden 1 cisim köşegeni bulunur.'),
  ('Taban alanı 24 cm² ve hacmi 120 cm³ olan bir beşgen dik prizmanın yüksekliği kaç santimetredir?', '5 santimetre', ['15 santimetre', '6 santimetre', '10 santimetre'], 'Bütün dik prizmalarda hacim Taban Alanı × Yükseklik formülüyle bulunur; 24 × h = 120 eşitliğinden yükseklik h = 5 cm çıkar.'),
  ('Bir dikdörtgenler prizmasının toplam kaç tane cisim köşegeni vardır ve bunların uzunlukları birbirine göre nasıldır?', '4 tanedir ve dördünün de uzunluğu birbirine eşittir', ['2 tanedir ve uzunlukları birbirinden farklıdır', '4 tanedir ve ikişerli olarak farklı uzunluktadır', '8 tanedir ve dördü uzun dördü kısadır'], 'Dikdörtgenler prizmasının karşılıklı 4 çift köşesini birleştiren 4 cisim köşegeni vardır ve hepsinin uzunluğu √(a² + b² + c²) olup birbirine eşittir.'),
  ('Taban çevresi 28 cm olan düzgün yedigen piramidin yan yüz yüksekliği (apotemi) 10 cm ise yanal alanı kaç santimetrekaredir?', '140 santimetrekare', ['280 santimetrekare', '70 santimetrekare', '210 santimetrekare'], 'Düzgün piramitlerde yanal alan (Taban Çevresi × Yan Yüz Yüksekliği) / 2 formülüyle (28 × 10) / 2 = 140 cm² olarak hesaplanır.'),
  ('Düzgün bir piramidin düzlemsel açınımı yapıldığında ortada bir düzgün çokgen ve bu çokgenin her kenarına bitişik hangi eş şekiller görülür?', 'İkizkenar üçgenler', ['Dikdörtgenler', 'Çeşitkenar üçgenler', 'Dik yamuklar'], 'Düzgün piramitlerin tüm yan ayrıtları birbirine eşit olduğundan, taban kenarlarına yapışık yan yüzlerin tamamı birbirine eş ikizkenar üçgenlerdir.'),
  ('Platonik cisimler olarak bilinen beş düzgün çokyüzlüden hangileri aynı zamanda prizma veya piramit sınıfında yer alır?', 'Küp ve düzgün dörtyüzlü', ['Düzgün sekizyüzlü ve küp', 'Düzgün onikiyüzlü ve düzgün dörtyüzlü', 'Düzgün yirmiyüzlü ve düzgün sekizyüzlü'], 'Beş Platonik cisim içinde küp özel bir kare dik prizma, düzgün dörtyüzlü ise özel bir düzgün üçgen piramittir.'),
  ('Tabanı eşkenar dörtgen olan bir dik prizmanın taban köşegenleri 6 cm ve 8 cm, yüksekliği ise 5 cm olduğuna göre hacmi kaç santimetreküptür?', '120 santimetreküp', ['240 santimetreküp', '100 santimetreküp', '160 santimetreküp'], 'Eşkenar dörtgenin alanı köşegenler çarpımının yarısı olduğundan (6 × 8) / 2 = 24 cm²\'dir; prizmanın hacmi 24 × 5 = 120 cm³ olur.'),
  ('Kesik bir düzgün piramidin üst taban düzlemi ile alt taban düzlemi arasındaki geometrik ilişki aşağıdakilerden hangisidir?', 'Birbirine paralel ve benzer iki düzgün çokgendir', ['Birbirine eş ve paralel iki düzgün çokgendir', 'Birbirini dik kesen iki farklı çokgendir', 'Alanları eşit fakat kenar sayıları farklı iki çokgendir'], 'Kesik piramit, düzgün piramidin tabana paralel bir düzlemle kesilmesiyle oluştuğundan alt ve üst tabanlar birbirine paralel ve benzer düzgün çokgenlerdir.'),
  ('Hacmi 100 cm³ ve yüksekliği 12 cm olan bir kare dik piramidin taban çevresi kaç santimetredir?', '20 santimetre', ['25 santimetre', '16 santimetre', '40 santimetre'], 'V = (a² × 12) / 3 = 4a² = 100 eşitliğinden a² = 25 ve taban ayrıtı a = 5 cm bulunur; kare tabanın çevresi 4 × 5 = 20 cm\'dir.'),
  ('Üçgen dik prizmanın düzlemsel açınımında kaç adet dikdörtgensel bölge ve kaç adet üçgensel bölge yer alır?', '3 dikdörtgensel bölge ve 2 üçgensel bölge', ['2 dikdörtgensel bölge ve 3 üçgensel bölge', '3 dikdörtgensel bölge ve 1 üçgensel bölge', '4 dikdörtgensel bölge ve 2 üçgensel bölge'], 'Üçgen dik prizmanın 3 yan yüzü dikdörtgen, alt ve üst tabanları ise birbirine eş 2 üçgendir.'),
  ('İç taban ayrıtları 5 dm ve 4 dm olan dikdörtgenler prizması biçimindeki bir akvaryuma 60 litre su konulduğunda suyun yüksekliği kaç desimetre olur?', '3 desimetre', ['4 desimetre', '2,5 desimetre', '6 desimetre'], '1 litre = 1 dm³ olduğundan suyun hacmi 60 dm³\'tür. Taban alanı 5 × 4 = 20 dm² olduğundan su yüksekliği 60 / 20 = 3 dm bulunur.'),
  ('Bir karıncanın bir prizmanın yüzeyi üzerinden iki nokta arasında alabileceği en kısa yolu hesaplarken kullanılan temel geometrik yöntem hangisidir?', 'Yüzeyleri aynı düzlem üzerine açıp iki noktayı doğrusal birleştirmek', ['Cisim köşegenini hesaplayıp yüzey sayısına bölmek', 'Ayrıtlar üzerinden sadece dik açılarla yürütülen yolları toplamak', 'Prizmanın hacmini taban çevresine oranlamak'], 'Eğrisel veya kırıklı yüzeylerde geodezik (en kısa) mesafe, geçilen düzlemsel yüzler kat yerlerinden aynı düzleme açıldığında iki noktayı birleştiren doğru parçasıdır.'),
  ('Taban ayrıtı a olan bir eşkenar üçgen dik prizmanın yüksekliği h ise prizmanın hacmini veren ifade hangisidir?', '(a²√3 / 4) × h', ['(a²√3 / 2) × h', '(a²√3 / 12) × h', '(a² / 2) × h'], 'Eşkenar üçgenin taban alanı a²√3 / 4 olduğundan dik prizmanın hacmi bu alan ile h yüksekliğinin çarpımına eşittir.'),
  ('Yanal alanı 160 cm² ve yüksekliği 8 cm olan kare dik prizmanın bir taban ayrıtı kaç santimetredir?', '5 santimetre', ['4 santimetre', '8 santimetre', '10 santimetre'], 'Yanal alan Taban Çevresi × Yükseklik = 4a × 8 = 32a = 160 olduğundan taban ayrıtı a = 5 cm bulunur.'),
  ('Taban alanları eşit ve yükseklikleri eşit olan bir kare dik prizma ile bir kare dik piramidin hacimleri oranı (Prizma / Piramit) kaçtır?', '3', ['2', '4', '6'], 'Aynı taban alanına ve aynı yüksekliğe sahip prizmanın hacmi S×h iken piramidin hacmi (S×h)/3 olduğundan oran 3\'tür.'),
  ('Tüm ayrıtlarının uzunlukları toplamı 76 cm olan bir dikdörtgenler prizmasının iki farklı ayrıtı 5 cm ve 6 cm ise üçüncü ayrıtı kaç santimetredir?', '8 santimetre', ['9 santimetre', '7 santimetre', '10 santimetre'], 'Dikdörtgenler prizmasında her ayrıttan 4\'er tane vardır: 4(5 + 6 + c) = 76 ise 11 + c = 19 ve c = 8 cm bulunur.'),
  ('Bir küpün karşılıklı iki yüzünün merkezlerini birleştiren doğru parçasının uzunluğu küpün hangi elemanına eşittir?', 'Küpün bir ayrıtının uzunluğuna', ['Küpün yüzey köşegeninin yarısına', 'Küpün cisim köşegeninin yarısına', 'Küpün taban çevresinin yarısına'], 'Karşılıklı paralel yüzlerin merkezlerini birleştiren doğru parçası tabanlara diktir ve uzunluğu doğrudan küpün yüksekliğine yani bir ayrıtına eşittir.'),
  ('Yarıçapı r olan bir kürenin tüm yüzey alanını veren cebirsel bağıntı aşağıdakilerden hangisidir?', '4πr²', ['(4/3)πr³', '2πr² + 2πrh', 'πr² + πrl'], 'Kürenin toplam yüzey alanı, yarıçapı r olan en büyük kesit dairesinin alanının dört katına yani 4πr² değerine eşittir.'),
  ('Yarıçap uzunluğu r birim olan içi dolu bir kürenin hacmini ifade eden bağıntı hangisidir?', '(4/3)πr³', ['4πr² + 2πr', '(1/3)πr²h', '(2/3)πr³h'], 'Yarıçapı r olan tam bir kürenin hacmi (4/3)πr³ formülüyle hesaplanır.'),
  ('Merkezinden geçen herhangi bir düzlemle iki eş parçaya ayrılan kürenin oluşan dairesel ara kesitine ne ad verilir?', 'Büyük daire', ['Küresel kuşak', 'İkizkenar yamuk', 'Dikdörtgen kesit'], 'Kürenin bir düzlemle ara kesiti daima dairedir; düzlem merkezden geçtiğinde oluşan en geniş kesite büyük daire denir.'),
  ('Yarıçapı 3 birim olan bir kürenin yüzey alanı kaç π birimkaredir?', '36', ['108', '27 ile 30 arası', '48 birimkare'], 'Yüzey alanı 4πr² bağıntısından 4 · π · 3² = 36π birimkare olarak bulunur.'),
  ('Çapı 12 cm olan küre biçimindeki cam bir kürenin hacmi kaç π santimetreküptür?', '288', ['144', '432', '576'], 'Çapı 12 cm ise yarıçap r = 6 cm olur; hacim (4/3) · π · 6³ = (4/3) · 216π = 288π cm³ bulunur.'),
  ('Yüzey alanı 100π birimkare olan bir kürenin çap uzunluğu kaç birimdir?', '10', ['20', '25', '15'], '4πr² = 100π eşitliğinden r² = 25 ve r = 5 birim bulunur; çap uzunluğu ise 2r = 10 birimdir.'),
  ('Hacmi 36π cm³ olan küre şeklindeki oyun hamurunun yarıçap uzunluğu kaç santimetredir?', '3', ['6', '12', '18'], '(4/3)πr³ = 36π eşitliğinden r³ = 27 elde edilir ve buradan yarıçap r = 3 cm çıkar.'),
  ('Yarıçapı r olan içi dolu bir yarım kürenin toplam yüzey alanı (taban dairesi dahil) kaç πr² olur?', '3', ['2,5', '3,5', '4,5'], 'Yarım kürenin eğri yüzey alanı 2πr², düz taban dairesinin alanı ise πr² olduğundan toplam yüzey alanı 3πr² eder.'),
  ('Yarıçapı 4 birim olan içi dolu metal bir yarım kürenin tüm yüzey alanı kaç π birimkaredir?', '48', ['32', '64', '96'], 'Dolu yarım kürenin tüm alanı 3πr² formülüyle 3 · π · 4² = 48π birimkare hesaplanır.'),
  ('Yarıçapı 10 cm olan bir küre, merkezinden 6 cm uzaklıktaki bir düzlemle kesildiğinde oluşan kesit dairesinin yarıçapı kaç cm olur?', '8', ['12', '14', '16'], 'Merkezden kesit dairesine inen dikme kesit merkezinden geçer; Pisagor teoreminden 6² + x² = 10² ile kesit yarıçapı x = 8 cm bulunur.'),
  ('Yarıçapı 13 birim olan bir kürenin merkezinden 12 birim uzaklıkta alınan düzlemsel kesitin alanı kaç π birimkaredir?', '25', ['144', '169', '125'], 'Kesit yarıçapı Pisagor bağıntısıyla √(13² - 12²) = 5 birimdir; kesit dairesinin alanı π · 5² = 25π birimkaredir.'),
  ('Bir küpün tüm yüzlerine içten teğet olan kürenin çapı, küpün hangi elemanının uzunluğuna eşittir?', 'Bir ayrıt uzunluğuna', ['Yüzey köşegeninin uzunluğuna', 'Cisim köşegeninin uzunluğuna', 'Taban çevresinin yarısına'], 'Küpün karşılıklı iki paralel yüzü arasındaki dik uzaklık bir ayrıt kadardır; içten teğet kürenin çapı bu uzaklığa eşittir.'),
  ('Bir küpün sekiz köşesinden de geçen çevrel kürenin çapı, küpün hangi uzunluğuna eşittir?', 'Cisim köşegenine', ['Yüzey köşegeninin iki katına', 'Bir ayrıt uzunluğunun yarısına', 'Üç ayrıtının toplamına'], 'Küpün ağırlık merkezi sekiz köşeye eşit uzaklıktadır; dolayısıyla çevrel kürenin çapı küpün cisim köşegenine (a√3) eşittir.'),
  ('Yarıçapı 5 cm olan sert bir küreyi tamamen içine alabilecek en küçük hacimli küpün bir ayrıtı kaç santimetredir?', '10', ['15', '5√2', '10√3'], 'Kürenin çapı 10 cm olduğundan onu tamamen saran en küçük küpün karşılıklı yüzleri arası uzaklık, yani bir ayrıtı 10 cm olmalıdır.'),
  ('En büyük kesit dairesinin çevresi 14π birim olan bir kürenin yüzey alanı kaç π birimkaredir?', '196', ['144', '256', '324'], 'Büyük dairenin çevresi 2πr = 14π ise r = 7 birimdir; kürenin yüzey alanı 4πr² = 4π · 49 = 196π birimkare olur.'),
  ('Merkezinden geçen dairesel kesitinin alanı 9π cm² olan bir kürenin tüm yüzey alanı kaç cm² değerindedir?', '36π', ['18π', '27π', '72π'], 'Büyük dairenin alanı πr² = 9π olduğundan kürenin yüzey alanı bunun dört katı, yani 4πr² = 36π cm² olur.'),
  ('Taban yarıçapı r ve yüksekliği 2r olan dik dairesel silindirin içine hem tabanlara hem yan yüzeye teğet olacak biçimde yerleştirilen kürenin yarıçapı nedir?', 'r', ['2r', 'r√2', 'r√3'], 'Silindirin yüksekliği 2r ve taban çapı 2r olduğundan içine tam oturan teğet kürenin çapı 2r, yarıçapı ise r olur.'),
  ('İç yarıçapı 6 birim olan küre biçimindeki cam fanusun tam yarısı su ile doluyken içindeki suyun hacmi kaç π birimküptür?', '144', ['288', '216', '108'], 'Tam küre hacmi (4/3)π · 6³ = 288π birimküptür; yarısı dolu olduğundan su hacmi 144π birimküp olur.'),
  ('Merkez açısı 90° olan bir küre diliminin hacmi, aynı kürenin tam hacminin kaçta kaçıdır?', '1/4', ['1/3', '1/6', '1/8'], 'Tam açı 360° olduğundan 90° merkez açılı küre diliminin hacmi tam küre hacminin 90/360 = 1/4 katıdır.'),
  ('Yarıçapı 3 cm olan küreden 60° merkez açılı bir küre dilimi kesilip çıkarılırsa bu dilimin hacmi kaç π cm³ olur?', '6', ['12', '18', '24'], 'Tam hacim (4/3)π · 3³ = 36π cm³ olup 60° dilim bunun 60/360 = 1/6 katıdır; 36π / 6 = 6π cm³ bulunur.'),
  ('Küre biçimindeki bir karpuz tam merkezinden düz bir bıçakla iki eş yarım küreye ayrıldığında oluşan iki parçanın toplam yüzey alanı başlangıca göre nasıl değişir?', '%50 artar', ['Hiç değişmez', '%25 oranında artar', 'İki katına çıkar'], 'Başlangıçta alan 4πr² iken kesim sonrası iki yeni daire yüzeyi (2πr²) eklenir ve toplam alan 6πr² olur; artış oranı 2/4 = %50\'dir.'),
  ('Cisim köşegeninin uzunluğu 16 birim olan bir küpün tüm köşelerinden geçen çevrel kürenin yarıçapı kaç birimdir?', '8', ['16', '8√3', '4√3'], 'Küpün çevrel küresinin çapı cisim köşegenine (16 birim) eşit olduğundan yarıçapı 16 / 2 = 8 birimdir.'),
  ('Benzerlik oranı k olan iki benzer katı cismin yüzey alanları arasındaki oran aşağıdakilerden hangisidir?', 'k²', ['k³', '2k', '3k²'], 'Benzer katı cisimlerde doğrusal boyutlar oranı k iken karşılıklı yüzey alanlarının oranı benzerlik oranının karesine yani k² değerine eşittir.'),
  ('Benzerlik oranı k olan iki benzer üç boyutlu cismin hacimleri oranı aşağıdakilerden hangisine eşittir?', 'k³', ['k²', '3k', '4k³'], 'Üç boyutlu benzer cisimlerde hacimler oranı doğrusal benzerlik oranının küpüne (k³) eşittir.'),
  ('Yarıçapı 3 katına çıkarılan küre biçimindeki esnek bir balonun yüzey alanı kaç katına çıkar?', '9', ['27', '6', '12'], 'Doğrusal ölçek katsayısı k = 3 olduğundan yüzey alanı k² = 3² = 9 katına çıkar.'),
  ('1/50 ölçekle küçültülerek hazırlanan mimari bir bina maketinin dış cephe boyama alanı, gerçek binanın ilgili dış cephe alanının kaçta kaçıdır?', '1/2500', ['1/50', '1/125000', '1/250'], 'Ölçek oranı k = 1/50 olduğundan yüzey alanları oranı k² = (1/50)² = 1/2500 olur.'),
  ('Bir küpün bir ayrıt uzunluğu %100 artırıldığında yüzey alanı yüzde kaç artar?', '300', ['100', '200', '400'], 'Ayrıt %100 artarsa 2 katına çıkar; yüzey alanı 2² = 4 katına çıkacağından artış miktarı 4 - 1 = 3 kat yani %300 olur.'),
  ('Bir kürenin yarıçap uzunluğu yarıya indirildiğinde hacmi başlangıçtaki hacminin kaçta kaçına düşer?', '1/8', ['1/4', '1/2', '1/6'], 'Yarıçap 1/2 katına indiğinde hacim (1/2)³ = 1/8 katına düşer.'),
  ('Yüzey alanları oranı 4/9 olan iki benzer dik koninin yükseklikleri oranı kaçtır?', '2/3', ['8/27', '16/81', '4/9'], 'Yüzey alanları oranı k² = 4/9 olduğundan doğrusal benzerlik oranı (yükseklikleri oranı) k = √(4/9) = 2/3 bulunur.'),
  ('Hacimleri oranı 8/125 olan iki benzer kare piramidin taban çevreleri oranı kaçtır?', '2/5', ['4/25', '8/25', '4/15'], 'Hacimler oranı k³ = 8/125 ise doğrusal benzerlik oranı k = ∛(8/125) = 2/5 olup taban çevreleri oranı da k = 2/5\'tir.'),
  ('Yüzey alanları oranı 16/25 olan iki kürenin hacimleri oranı kaçtır?', '64/125', ['4/5', '32/75', '256/625'], 'k² = 16/25 eşitliğinden yarıçaplar oranı k = 4/5 bulunur; hacimler oranı ise k³ = (4/5)³ = 64/125 olur.'),
  ('Birim küplerin aralarında boşluk kalmayacak biçimde birleştirilmesiyle oluşturulan 3×3×3 boyutlarındaki büyük küp toplam kaç birim küpten meydana gelir?', '27', ['18', '36', '54'], 'Boyutları 3, 3 ve 3 birim olan dolu küpteki birim küp sayısı 3 · 3 · 3 = 27 adettir.'),
  ('2×2×2 boyutlarında 8 birim küpten oluşan bir küpün tüm dış yüzeyi maviye boyanıp birim küpler birbirinden ayrılıyor. Hiçbir yüzü boyanmamış kaç birim küp vardır?', '0', ['1', '2', '4'], '2×2×2 küpteki 8 birim küpün tamamı köşe küpüdür ve her birinin 3 yüzü boyanır; içte gizli küp olmadığından boyasız küp sayısı 0\'dır.'),
  ('3×3×3 boyutlarındaki 27 birim küpten oluşan küpün tüm dış yüzeyi kırmızıya boyanıp ayrıldığında hiçbir yüzü boyalı olmayan kaç birim küp çıkar?', '1', ['0', '6', '8'], 'İç kısımda kalan boyasız küpler (n - 2)³ formülüyle (3 - 2)³ = 1³ = 1 adet (tam merkezdeki küp) olarak bulunur.'),
  ('3×3×3 boyutlarındaki küpün dış yüzeyi tamamen boyanıp birim küplere ayrıldığında yalnızca 1 yüzü boyalı kaç birim küp elde edilir?', '6', ['8', '12', '9'], 'Yalnızca 1 yüzü boyalı küpler her bir yüzün ortasında yer alır; 6 yüzün her birinde (3 - 2)² = 1 adet bulunduğundan toplam 6 · 1 = 6 adettir.'),
  ('3×3×3 boyutlarındaki bir küpün tüm dış yüzeyi sarıya boyanıp parçalandığında tam olarak 2 yüzü boyalı olan birim küp sayısı kaçtır?', '12', ['8', '6', '24'], 'İki yüzü boyalı küpler ayrıtların köşeler hariç orta kısımlarındadır; 12 ayrıtın her birinde (3 - 2) = 1 adet olduğundan toplam 12 · 1 = 12 adettir.'),
  ('Birbirine yapıştırılmış birim küplerden oluşan katı bir yapının köşesinden, diğer küplerin bağlantısını koparmadan bir birim küp söküldüğünde hacmi nasıl değişir?', '1 birimküp azalır', ['Değişmez', '3 birimküp azalır', '2 birimküp azalır'], 'Her birim küpün hacmi 1 birimküp olduğundan yapıdan bir adet birim küp çıkarıldığında toplam hacim 1 birimküp azalır.'),
  ('4 adet özdeş birim küp yan yana tek bir doğrusal sıra halinde (1×1×4 prizma) yapıştırıldığında oluşan cismin tüm yüzey alanı kaç birimkaredir?', '18', ['24', '16', '20'], 'Ayrıtları 1, 1 ve 4 birim olan kare dik prizmanın yüzey alanı 2 · (1·1 + 1·4 + 1·4) = 2 · 9 = 18 birimkaredir.'),
  ('Birim küplerle 1. katında 4 küp (2×2), 2. katında ise 1 küp bulunan kule yapısının toplam hacmi kaç birimküptür?', '5', ['6', '8', '4'], 'Yapıda toplam 4 + 1 = 5 adet birim küp kullanıldığından cismin hacmi 5 birimküptür.'),
  ('Yüksekliğinin tam ortasından tabana paralel bir düzlemle kesilen dik dairesel konide, üstte oluşan küçük koninin taban yarıçapı ana koninin taban yarıçapının kaçta kaçıdır?', '1/2', ['1/4', '1/3', '1/8'], 'Tepe noktasından itibaren yükseklikler oranı 1/2 olduğundan üçgen benzerliğinden yarıçaplar oranı da 1/2 olur.'),
  ('Bir heykelin aynı maddeden yapılmış 1/3 ölçekli minyatür kopyasının kütlesi 2 kg ise gerçek heykelin kütlesi kaç kilogramdır?', '54', ['18', '27', '36'], 'Aynı özkütleli maddede kütle hacimle doğru orantılıdır; boyut oranı 3 olduğundan gerçek kütle 2 · 3³ = 2 · 27 = 54 kg olur.'),
  ('5×5×5 boyutlarındaki birim küp bloğunun yalnız en üst yüzeyi boyandığında kaç adet birim küpün 1 yüzü boyanmış olur?', '25', ['20', '16', '125'], 'Sadece tek bir dış yüz (üst yüz) boyandığı için o yüzü oluşturan 5 · 5 = 25 birim küpün her birinin yalnızca üstteki 1 yüzü boyanır.'),
  ('Dört yüzü, beş yüzü veya altı yüzü boyalı birim küp elde edebilmek için dış yüzeyi boyanan n×n×n küpte n tam sayısı ne olmalıdır?', 'yalnızca n = 1', ['n = 2', 'n = 3', 'n ≥ 4'], 'n ≥ 2 için bir birim küpün en fazla 3 yüzü dışarı bakar; 6 yüzünün birden boyanması ancak tek başına duran n = 1 birim küpte mümkündür (4 veya 5 yüzü boyalı küp ise n×n×n küpte hiç oluşmaz).'),
  ('Dik dairesel bir silindirin yan yüzeyinin düzlem üzerine açınımı hangi geometrik şekli oluşturur?', 'Dikdörtgen', ['Daire dilimi', 'İkizkenar yamuk', 'Eşkenar üçgen'], 'Dik silindirin yan yüzeyi açıldığında taban çevresi ve yükseklik kenarlarına sahip bir dikdörtgen elde edilir.'),
  ('Dik dairesel bir koninin yan yüzeyinin düzleme açınımı aşağıdakilerden hangisidir?', 'Daire dilimi', ['Dikdörtgen levha', 'Düzgün altıgen', 'Paralelkenar bölge'], 'Dik koninin yanal yüzeyi tepe noktasından bir ana doğru boyunca kesilip açıldığında yarıçapı ana doğruya eşit bir daire dilimi oluşur.'),
  ('Taban yarıçapı 3 cm ve ana doğrusu 12 cm olan dik dairesel koninin yan yüzeyi açıldığında oluşan daire diliminin merkez açısı kaç derecedir?', '90', ['120', '150', '108'], 'r/a = α/360 bağıntısından 3/12 = α/360 yazılır; buradan α = 360/4 = 90 derece elde edilir.'),
  ('Bir dik üçgenin dik kenarlarından biri etrafında 360 derece döndürülmesiyle oluşan döner cisim aşağıdakilerden hangisidir?', 'Dik dairesel koni', ['Dik dairesel silindir', 'Kesik dairesel koni', 'Eğik kare prizma'], 'Dik üçgen dik kenarlarından biri etrafında tam tur döndürüldüğünde diğer dik kenar taban yarıçapını, hipotenüs ise ana doğruyu oluşturarak dik dairesel koni meydana getirir.'),
  ('Bir dikdörtgenin herhangi bir kenarı etrafında 360 derece döndürülmesi sonucunda hangi katı cisim elde edilir?', 'Dik dairesel silindir', ['Dik dairesel koni', 'Eşkenar dairesel koni', 'Düzgün kare dik prizma'], 'Dikdörtgen bir kenarı etrafında tam tur döndüğünde sabit kenar yüksekliği, dik olan komşu kenar ise taban yarıçapını tarayarak dik dairesel silindir oluşturur.'),
  ('Bir dik yamuğun tabanlara dik olan yan kenarı etrafında 360 derece döndürülmesiyle oluşan cisim nedir?', 'Kesik dik koni', ['Dik dairesel silindir', 'Çift tabanlı dik koni', 'Dik yamuksal prizma'], 'Dik yamuk dik yan kenarı etrafında 360 derece döndürüldüğünde alt ve üst tabanlar iki farklı yarıçaplı daire tarar ve kesik dik koni oluşur.'),
  ('Ana doğru uzunluğu taban çapına eşit olan dik dairesel koniye eşkenar koni denir. Bir eşkenar koninin yan yüzey açınımındaki daire diliminin merkez açısı kaç derecedir?', '180', ['120', '240', '150'], 'Eşkenar konide ana doğru a = 2r olduğundan r/a = 1/2 olur; α/360 = 1/2 eşitliğinden α = 180 derece bulunur.'),
  ('Tamamen su ile dolu dik dairesel silindir biçimindeki bir kap yatay düzlemle 45 derecelik açı yapacak biçimde eğildiğinde su yüzeyi üst taban çemberinin bir noktasına ve yan yüzeye değmektedir. Dökülen suyun hacmi aşağıdakilerden hangisine eşittir?', 'Üstte oluşan eğik kesitli silindir bölgesinin hacminin yarısına', ['Silindirin başlangıçtaki toplam su hacminin tam yarısına', 'Alt taban yarıçapının küpü ile π sayısının iki katının çarpımına', 'Yan yüzey alanının taban yarıçapının yarısıyla çarpımına'], 'Eğik tutulan silindirde su yüzeyi yatay kaldığından, su yüzeyinin yan yüzeyi kestiği en alt noktadan geçen tabana paralel düzlem ile üst taban arasında kalan silindir parçasının tam yarısı dökülür.'),
  ('Yarıçapı 6 cm olan çeyrek daire biçimindeki ince bir karton, düz kenarları çakışacak biçimde kıvrılarak tepesi kapalı tabanı açık bir dik koni yapılıyor. Bu koninin taban yarıçapı kaç santimetredir?', '3/2', ['5/2', '7/2', '4/3'], 'Çeyrek dairenin merkez açısı 90 derece ve yarıçapı koninin ana doğrusu a = 6 cm\'dir. r/6 = 90/360 = 1/4 olduğundan r = 6/4 = 3/2 cm bulunur.'),
  ('Kenar uzunlukları 3 cm ve 7 cm olan bir dikdörtgen, uzun kenarı etrafında 360 derece döndürülüyor. Oluşan cismin hacmi kaç π santimetreküptür?', '63', ['147', '126', '42'], 'Uzun kenar (7 cm) yükseklik h = 7 cm, kısa kenar (3 cm) yarıçap r = 3 cm olur. Hacim π·r²·h = π·9·7 = 63π cm³ bulunur.'),
  ('Dik kenarları 6 cm ve 8 cm olan bir dik üçgen, 8 cm uzunluğundaki dik kenarı etrafında 360 derece döndürülüyor. Elde edilen koninin hacmi kaç π santimetreküptür?', '96', ['128', '288', '144'], 'Dönme ekseni 8 cm olduğundan h = 8 cm ve r = 6 cm olur. Koni hacmi (1/3)·π·r²·h = (1/3)·π·36·8 = 96π cm³ bulunur.'),
  ('Bir dik dairesel koni, tabana paralel bir düzlemle yüksekliği iki eş parçaya bölünecek biçimde tam ortadan kesiliyor. Üstte oluşan küçük koninin hacminin kesilmeden önceki tüm koninin hacmine oranı kaçtır?', '1/8', ['1/4', '1/2', '1/6'], 'Benzerlik oranı k = 1/2 olduğundan hacimler oranı k³ = (1/2)³ = 1/8 olur.'),
  ('Bir yarım dairenin kendi çapı etrafında 360 derece döndürülmesiyle oluşan döner cisim aşağıdakilerden hangisidir?', 'Küre', ['Eşkenar koni', 'Dik silindir', 'Yarım küre'], 'Yarım daire kendi çapı etrafında 360 derece döndürüldüğünde uzayda tam bir küre tarar.'),
  ('Alt taban yarıçapı 6 cm, üst taban yarıçapı 3 cm ve yüksekliği 4 cm olan bir kesik dik koninin ana doğru uzunluğu kaç santimetredir?', '5', ['√29', '√34', '10'], 'Dik yamuk kesitinde yarıçap farkı 6 - 3 = 3 cm ve yükseklik 4 cm olduğundan Pisagor teoreminden ana doğru a = √(3² + 4²) = 5 cm bulunur.'),
  ('Alt taban yarıçapı R, üst taban yarıçapı r ve ana doğru uzunluğu a olan bir kesik dik koninin yanal alanı hangi ifadeyle hesaplanır?', 'π·(R + r)·a', ['π·(R - r)·a', '2·π·(R + r)·a', '(1/3)·π·(R² + r²)·a'], 'Kesik koninin yanal yüzeyi yamuk alanına benzer biçimde taban çevreleri toplamının yarısı ile ana doğrunun çarpımına, yani π·(R + r)·a değerine eşittir.'),
  ('Dışbükey bir çokyüzlünün köşe sayısı V, ayrıt sayısı E ve yüz sayısı F olmak üzere Euler çokyüzlü teoremi aşağıdakilerden hangisidir?', 'V - E + F = 2', ['V + E - F = 2 eşitliği', 'V - E - F = 2 bağıntısı', 'V + E + F = 2 kuralı'], 'Euler formülü tüm dışbükey çokyüzlülerde V - E + F = 2 biçiminde sağlanır.'),
  ('Tüm yüzleri birbirine eş eşkenar üçgenlerden oluşan beş Platon cisminden sekiz yüzlü olanı hangisidir?', 'Düzgün sekizyüzlü', ['Düzgün onikiyüzlü', 'Düzgün yirmiyüzlü', 'Düzgün altıyüzlü'], 'Oktahedron yani düzgün sekizyüzlü, sekiz adet eş eşkenar üçgen yüzden meydana gelir.'),
  ('Ayrıt uzunluğu a birim olan bir küpün cisim köşegeninin uzunluğu aşağıdakilerden hangisine eşittir?', 'a√3', ['a√2 uzunluğu', '2a uzunluğu', '3a√2 değeri'], 'Küpün cisim köşegeni Pisagor teoremiyle √(a²+a²+a²) = a√3 olarak hesaplanır.'),
  ('Bir dik dairesel koninin tabanına paralel bir düzlemle kesilmesiyle oluşan ara kesit yüzeyi hangi geometrik şekildir?', 'Daire', ['Dikdörtgen bölgesi', 'İkizkenar yamuk', 'Elips eğrisi yüzeyi'], 'Dik dairesel koni tabana paralel kesildiğinde tabana benzer bir daire oluşur.'),
  ('Yüzleri düzgün beşgenlerden oluşan Platon cismi olan düzgün onikiyüzlünün toplam köşe sayısı kaçtır?', '20', ['12 köşe noktası', '30 köşe noktası', '24 köşe noktası'], 'Düzgün onikiyüzlüde F=12, her yüz 5 ayrıtlı olduğundan E=(12·5)/2=30 ve Euler\'den V=20 bulunur.'),
  ('Uzayda bir doğru bir düzleme dik ise, bu doğru düzlem üzerindeki doğrularla nasıl bir ilişki içindedir?', 'Düzlemdeki her doğruya diktir', ['Yalnızca paralel doğrulara diktir', 'Düzlemdeki hiçbir doğruyu kesmez', 'Yalnızca tek bir doğruya diktir'], 'Bir düzleme dik olan doğru, o düzlem içinde bulunan ve ayağından geçen tüm doğrulara diktir.'),
  ('Bir dikdörtgenin kendi kenarlarından biri etrafında 360 derece döndürülmesiyle oluşan dönel cisim hangisidir?', 'Dik dairesel silindir', ['Dik dairesel koni cismi', 'Kesik dik dairesel koni', 'Küre dilimi geometrisi'], 'Dikdörtgen bir kenarı etrafında 360° döndürüldüğünde diğer kenar yarıçap olmak üzere dik silindir oluşur.'),
  ('Bir küpün bir yüzünün alanı 25 cm² olduğuna göre hacmi kaç cm³\'tür?', '125', ['150 santimetreküp', '100 santimetreküp', '75 santimetreküp'], 'Bir ayrıtı a = √25 = 5 cm olan küpün hacmi a³ = 125 cm³ olur.'),
  ('Aynı düzlemde bulunmayan ve kesişmeyen iki uzay doğrusuna ne ad verilir?', 'Aykırı doğrular', ['Paralel uzay doğruları', 'Çakışık düzlem doğruları', 'Dik kesişen doğrular'], 'Uzayda ortak düzlem belirlemeyen ve kesişmeyen doğrulara aykırı doğrular denir.'),
  ('Bir dik üçgen, dik kenarlarından biri etrafında 360 derece döndürüldüğünde hangi katı cisim elde edilir?', 'Dik dairesel koni', ['Çift tabanlı dik koni', 'Dik dairesel silindir', 'Yarım küre katı cismi'], 'Dik kenar etrafında dönen dik üçgenin hipotenüsü koninin ana doğrusunu oluşturur.'),
  ('Düzgün yirmiyüzlünün (ikosahedron) her bir yüzü hangi düzgün çokgendir?', 'Eşkenar üçgen', ['Düzgün beşgen yüz', 'Kare biçimli yüz', 'Düzgün altıgen yüz'], 'Düzgün yirmiyüzlü 20 adet eş eşkenar üçgen yüzden oluşur.'),
  ('Ayrıtları 2 cm, 3 cm ve 6 cm olan dikdörtgenler prizmasının cisim köşegeni kaç cm\'dir?', '7', ['11 santimetre', '9 santimetre', '8 santimetre'], 'Cisim köşegeni √(2²+3²+6²) = √(4+9+36) = √49 = 7 cm bulunur.'),
  ('Bir kürenin merkezinden geçen herhangi bir düzlemle kesilmesi sonucu oluşan en büyük daireye ne ad verilir?', 'Büyük daire', ['Küre kapağı bölgesi', 'Küre kuşağı kesiti', 'Teğet daire düzlemi'], 'Merkezden geçen düzlem küreyi iki eş yarım küreye böler ve kesit büyük dairedir.'),
  ('Dik dairesel koninin yan yüzü açıldığında elde edilen düzlemsel şekil nedir?', 'Daire dilimi', ['Dikdörtgen levha', 'Eşkenar üçgen alanı', 'Dairesel halka parçası'], 'Koninin yanal yüzü açıldığında yarıçapı ana doğruya eşit bir daire dilimi oluşur.'),
  ('Uzayda doğrusal olmayan farklı üç nokta kaç tane düzlem belirler?', 'Yalnız bir düzlem', ['Sonsuz sayıda düzlem', 'En fazla iki düzlem', 'Üç farklı dik düzlem'], 'Doğrusal olmayan üç nokta uzayda tek bir düzlem tanımlar.'),
  ('Beş Platon cisminden yüzleri karelerden oluşan tek düzgün çokyüzlü hangisidir?', 'Düzgün altıyüzlü (küp)', ['Düzgün sekizyüzlü (oktahedron)', 'Düzgün onikiyüzlü (dodekahedron)', 'Düzgün dörtyüzlü (tetrahedron)'], 'Küp, tüm yüzleri birbirine eş altı kareden oluşan tek Platon cismidir.'),
  ('Uzayda bir doğru bir düzleme paralel ise bu doğrunun düzlemle ortak nokta sayısı kaçtır?', 'Sıfır', ['Yalnızca tek bir ortak nokta', 'İki farklı kesişim noktası', 'Sonsuz sayıda ortak nokta'], 'Düzleme paralel olan ve düzlemin dışında kalan doğru, düzlemi hiçbir noktada kesmez.'),
  ('Taban alanı 18 cm² ve yüksekliği 7 cm olan üçgen dik prizmanın hacmi kaç cm³\'tür?', '126', ['42 santimetreküp', '63 santimetreküp', '252 santimetreküp'], 'Prizma hacmi Taban Alanı · Yükseklik = 18·7 = 126 cm³ olur.'),
  ('Bir yarım daire, çapı etrafında 360 derece döndürüldüğünde oluşan katı cisim hangisidir?', 'Küre', ['Yarım küre cismi', 'Dik dairesel silindir', 'Çift tabanlı dik koni'], 'Yarım dairenin çapı etrafında tam dönmesiyle tam bir küre meydana gelir.'),
  ('Bir dikdörtgenler prizmasının birbirine paralel olmayan iki yüzünün kesişimi hangi geometrik elemanı oluşturur?', 'Bir ayrıt doğrusu', ['Yalnızca bir köşe noktası', 'Cisim köşegen doğrusu', 'Üçgensel düzlem parçası'], 'Prizmada kesişen iki yüz ortak bir ayrıt boyunca buluşur.'),
  ('Tüm yüzleri düzgün çokgenlerden oluşan ve her köşesinde aynı sayıda yüz birleşen beş dışbükey çokyüzlüye genel olarak ne ad verilir?', 'Platon cisimleri', ['Arşimet yarı düzgün cisimleri', 'Kepler-Poinsot yıldız cisimleri', 'Cavalieri eğik prizmaları'], 'Düzgün dörtyüzlü, küp, sekizyüzlü, onikiyüzlü ve yirmiyüzlüye Platon cisimleri denir.'),
  ('Uzayda kesişen iki farklı düzlemin ortak noktalarının oluşturduğu geometrik küme nedir?', 'Bir doğru', ['Tek bir kesişim noktası', 'Üçgensel düzlem bölgesi', 'Paralel iki doğru çifti'], 'Uzayda çakışık olmayan ve kesişen iki düzlem tam bir doğru boyunca kesişir.'),
  ('Bir beşgen dik prizmanın toplam ayrıt sayısı kaçtır?', '15', ['10 adet ayrıt', '12 adet ayrıt', '18 adet ayrıt'], 'n-gen prizmada 3n ayrıt bulunur; beşgen prizmada 3·5 = 15 ayrıt vardır.'),
  ('Bir kürenin yüzeyi ile tek bir ortak noktası bulunan düzleme küreye göre ne ad verilir?', 'Teğet düzlem', ['Ekvatoral kesit düzlemi', 'Merkezi simetri düzlemi', 'Normal dik kesit düzlemi'], 'Küreyi yalnızca bir noktada dokunarak paylaşan düzleme teğet düzlem denir.'),
  ('Taban çevresi 24 cm ve yüksekliği 7 cm olan kare dik prizmanın yanal alanı kaç cm²\'dir?', '168', ['84 santimetrekare', '196 santimetrekare', '144 santimetrekare'], 'Dik prizmada yanal alan Taban Çevresi · Yükseklik = 24·7 = 168 cm² olur.'),
  ('Bir ikizkenar yamuk, simetri ekseni (tabanların orta noktalarını birleştiren doğru) etrafında 180 derece döndürüldüğünde hangi cisim oluşur?', 'Kesik dik dairesel koni', ['Dik dairesel silindir cismi', 'Eğik tabanlı koni cismi', 'İki tabanlı koni birleşimi'], 'Simetri ekseni etrafında 180° dönen ikizkenar yamuk, tam bir kesik dik koni oluşturur.'),
];
